Date: Sun, 26 Apr 2015 17:21:15 -0500
Subject: [PATCH] channels/chan_skinny: Fix compilation error introduced in
 f8e21a1adf

A typo in commit f8e21a1adf resulted in a compilation error in
chan_skinny. This patch fixes the typo.

ASTERISK-24917

Change-Id: Id7f4ad1fe948eb2408622e80c27936ce4516c33c

diff --git a/channels/chan_skinny.c b/channels/chan_skinny.c
index 8f6f2eb7cc..5f30a13b56 100644
--- a/channels/chan_skinny.c
+++ b/channels/chan_skinny.c
@@ -7545,7 +7545,7 @@ static void *skinny_session(void *data)
 				break;
 			}

-			eventmessage = letohl(req-e);
+			eventmessage = letohl(req->e);
 			if (eventmessage < 0) {
 				ast_log(LOG_ERROR, "Event Message is NULL from socket %d, This is bad\n", s->fd);
 				break;
-- 
2.25.1

Code statements:
eventmessage = letohl(req-e);
eventmessage = letohl(req->e);

Code statements:
eventmessage = letohl(req-e);
eventmessage = letohl(req->e);

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
channels/chan_skinny: Fix compilation error introduced in
 f8e21a1adf

A typo in commit f8e21a1adf resulted in a compilation error in
chan_skinny. This patch fixes the typo.

ASTERISK-24917

Change-Id: Id7f4ad1fe948eb2408622e80c27936ce4516c33c

Here is the root cause:
The bug was caused by a typo in the code where the member of the `req` structure was incorrectly accessed using a minus sign (`-`) instead of the correct arrow operator (`->`). This resulted in a compilation error because the compiler could not interpret the expression correctly.

Here is the patch:

 static void *skinny_session(void *data)
 {
 	int res;
 	int bytesread;
 	struct skinny_req *req = NULL;
 	struct skinnysession *s = data;

 	int dlen = 0;
 	int eventmessage = 0;
 	struct pollfd fds[1];

 	if (!s) {
 		ast_log(LOG_WARNING, "Bad Skinny Session\n");
 		return 0;
 	}

 	ast_log(LOG_NOTICE, "Starting Skinny session from %s\n", ast_inet_ntoa(s->sin.sin_addr));

 	pthread_cleanup_push(skinny_session_cleanup, s);

 	s->start = ast_tvnow();
 	s->last_keepalive = ast_tvnow();
 	s->keepalive_count = 0;
 	s->lockstate = 0;

 	AST_LIST_LOCK(&sessions);
 	AST_LIST_INSERT_HEAD(&sessions, s, list);
 	AST_LIST_UNLOCK(&sessions);

 	s->auth_timeout_sched = ast_sched_add(sched, auth_timeout*1000, skinny_noauth_cb, s);
 	s->keepalive_timeout_sched = ast_sched_add(sched, keep_alive*3000, skinny_nokeepalive_cb, s);

 	for (;;) {

 		fds[0].fd = s->fd;
 		fds[0].events = POLLIN;
 		fds[0].revents = 0;
 		res = ast_poll(fds, 1, -1); /* block */
 		if (res < 0) {
 			if (errno != EINTR) {
 				ast_log(LOG_WARNING, "Select returned error: %s\n", strerror(errno));
 				ast_verb(3, "Ending Skinny session from %s (bad input)\n", ast_inet_ntoa(s->sin.sin_addr));
 				break;
 			}
 		}

 		if (fds[0].revents) {

 			if (!(req = ast_calloc(1, SKINNY_MAX_PACKET))) {
 				ast_log(LOG_WARNING, "Unable to allocated memorey for skinny_req.\n");
 				break;
 			}

 			ast_mutex_lock(&s->lock);
 			s->lockstate = 1;

 			if ((res = read(s->fd, req, skinny_header_size)) != skinny_header_size) {
 				if (res < 0) {
 					ast_log(LOG_WARNING, "Header read() returned error: %s\n", strerror(errno));
 				} else {
 					ast_log(LOG_WARNING, "Unable to read header. Only found %d bytes.\n", res);
 				}
 				break;
 			}

-			eventmessage = letohl(req-e);
+			eventmessage = letohl(req->e);
 			if (eventmessage < 0) {
 				ast_log(LOG_ERROR, "Event Message is NULL from socket %d, This is bad\n", s->fd);
 				break;
 			}

 			dlen = letohl(req->len) - 4;
 			if (dlen < 0) {
 				ast_log(LOG_WARNING, "Skinny Client sent invalid data.\n");
 				break;
 			}
 			if (dlen > (SKINNY_MAX_PACKET - skinny_header_size)) {
 				ast_log(LOG_WARNING, "Skinny packet too large (%d bytes), max length(%d bytes)\n", dlen+8, SKINNY_MAX_PACKET);
 				break;
 			}

 			bytesread = 0;
 			while (1) {
 				if ((res = read(s->fd, ((char*)&req->data)+bytesread, dlen-bytesread)) < 0) {
 					ast_log(LOG_WARNING, "Data read() returned error: %s\n", strerror(errno));
 					break;
 				}
 				bytesread += res;
 				if (bytesread >= dlen) {
 					if (res < bytesread) {
 						ast_log(LOG_WARNING, "Rest of partial data received.\n");
 					}
 					if (bytesread > dlen) {
 						ast_log(LOG_WARNING, "Client sent wrong amount of data (%d), expected (%d).\n", bytesread, dlen);
 						res = -1;
 					}
 					break;
 				}

 				ast_log(LOG_WARNING, "Partial data received, waiting (%d bytes read of %d)\n", bytesread, dlen);
 				if (sched_yield() < 0) {
 					ast_log(LOG_WARNING, "Data yield() returned error: %s\n", strerror(errno));
 					res = -1;
 					break;
 				}
 			}

 			s->lockstate = 0;
 			ast_mutex_unlock(&s->lock);
 			if (res < 0) {
 				break;
 			}

 			pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);
 			res = handle_message(req, s);
 			pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);
 		}

 		if (req) {
 			ast_free(req);
 			req = NULL;
 		}
 	}

 	ast_log(LOG_NOTICE, "Skinny Session returned: %s\n", strerror(errno));
 	if (req) {
 		ast_free(req);
 	}

 	pthread_cleanup_pop(1);

 	return 0;
 }



